// Shared cooperative arena. One host simulates the world; room snapshots connect up to four browsers.
let live=null,liveDraft=false,livePoll=null,liveBusy=false;
async function liveAPI(action,extra={}){const response=await fetch('/api/live/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...live?{code:live.code,token:live.token}:{},...extra})});const data=await response.json();if(!response.ok)throw Error(data.error||'Live room request failed.');return data}
function liveRoomLink(code){const u=new URL(window.location.href);u.search='';u.hash='room='+code;return u.href}
function liveHub(code=''){openModal(`${topModal('PLAY TOGETHER · LIVE CO-OP')}<h2 id="modal-title">Your crew. One battlefield.</h2><p class="sub">2–4 friends answer the same ten questions, earn their own life bars, then fight the bots together. See each other’s dog or cat avatars move and attack.</p><label class="nickname-label">Player nickname <input id="live-name" maxlength="20" value="${safeText(profile.playerName)}" placeholder="Choose a nickname"></label><div class="live-hub-actions"><button class="primary" data-live="create">Create a live room →</button><div class="live-join"><label>Friend’s room code <input id="live-code" maxlength="8" placeholder="8-character code" value="${safeText(code)}" autocomplete="off"></label><button class="secondary" data-live="join">Join friend →</button></div></div><p class="notice">No camera, microphone or chat. Your avatar and nickname are visible to people with the room code. The host must keep the game open. Rooms expire after two hours.</p>`)}
async function createLiveRoom(){try{const keys=buildQuestionDeck(fieldBanks(topicDraft)).slice(0,10).map(questionKey),data=await liveAPI('create',{name:profile.playerName,hero:ensureAvatar().id,level:playerLevel(),config:{stage:typeof missionStage==='function'?missionStage('arena'):1,threat:typeof missionThreat==='function'?missionThreat('arena'):1,map:typeof selectedCourse==='function'?selectedCourse('arena'):selectedMap().id,keys,timed:!!profile.questionTimed,mode:selectedMode().id,tier:questionStage().tier}});connectLive(data,true)}catch(e){toast(e.message)}}
function connectLive(data,host){liveBusy=false;clearQuestionClock();activeInvite=null;friendDraft=false;liveDraft=false;live={...data,host,phase:'lobby',players:[],state:{x:500,y:325,right:0,progress:0,ready:false,shot:0,super:0,moving:false},units:{},failures:0,lastPhase:'',roundStarted:false,battleStarted:false,ended:false,lastLobby:''};pollLive()}
function liveRoster(){return live.players.map(p=>`<article class="live-peer">${petPortrait(getBattleHero(p.hero,p.level,equipmentForPeer(p)))}<div><b>${safeText(p.name)} ${p.id===live.hostId?'♛':''}${p.id===live.selfId?' · YOU':''}</b><small>Level ${p.level} · ${p.connected?'Connected':'Reconnecting…'}${live.phase==='quiz'?' · '+(p.state.ready?'Ready · '+p.state.right+'/10':p.state.progress+'/10 answered'):''}</small></div></article>`).join('')}
function drawLiveLobby(){if(!live)return;const signature=JSON.stringify(live.players.map(p=>[p.id,p.name,p.connected,p.state.ready,p.state.progress,p.state.right,p.state.cosmetic]));if(live.lastLobby===signature&&modal.open)return;live.lastLobby=signature;const ready=live.players.length>=2&&live.players.every(p=>p.state.ready||!p.connected),quizPhase=live.phase==='quiz';openModal(`${topModal(quizPhase?'YOUR CREW IS CHARGING UP':'LIVE ROOM · '+live.code)}<h2 id="modal-title">${quizPhase?'Your hearts are ready.':'Friends, assemble.'}</h2><p class="sub">${quizPhase?'Wait for everyone to finish their ten questions. The host starts the shared battle.':'Share this room code with up to three friends. Everyone joins before the host starts.'}</p><div class="room-code">${live.code}</div><div class="live-roster">${liveRoster()}</div><label class="share-label">Invite link <input readonly id="live-invite" value="${safeText(liveRoomLink(live.code))}"></label><div class="modal-actions"><button class="secondary" data-live="copy">Copy invite link ↗</button>${live.host?`<button class="primary" data-live="${quizPhase?'battle':'start'}" ${(quizPhase?!ready:live.players.length<2)?'disabled':''}>${quizPhase?'Start shared battle →':'Start everyone’s 10 questions →'}</button>`:'<span class="notice">Waiting for the host…</span>'}<button class="text-btn" data-live="leave">Leave room</button></div><p class="notice">${live.config?(live.config.timed?'60 seconds per question':'No question time limit')+' · '+QUESTION_STAGES.find(s=>s.tier===live.config.tier)?.name+' questions · ':''}Keep this tab open to stay connected.</p>`)}
async function pollLive(){if(!live||liveBusy)return;liveBusy=true;const session=live;try{if(quiz&&live.roundStarted){live.state.progress=quiz.pos+(quiz.answered?1:0);live.state.right=quiz.right}if(game&&live.phase==='battle'){live.state.x=game.x;live.state.y=game.y;live.state.moving=game.moving}const data=await liveAPI('sync',{state:live.state,...live.host&&game&&live.battleStarted?{snapshot:liveSnapshot()}: {}});if(live!==session)return;Object.assign(live,{...data,failures:0});if(!data.hostAlive||data.phase==='closed'){endLiveConnection('The host left the room. Create or join a new room to play again.');return}if(data.phase==='lobby')drawLiveLobby();else if(data.phase==='quiz'){if(!live.roundStarted)startLiveQuestions();else if(live.state.ready)drawLiveLobby()}else if(data.phase==='battle'){if(!live.battleStarted)beginLiveBattle();if(!live.host&&data.snapshot?.players)applyLiveSnapshot(data.snapshot)}else if(data.phase==='results'&&!live.ended){if(data.snapshot?.players)applyLiveSnapshot({...data.snapshot,transport:'peer'});showLiveResults(data.snapshot?.win)};if(game&&live.host&&live.battleStarted)mergeLivePlayers();const badge=document.querySelector('#live-connection');if(badge)badge.textContent='● LIVE · '+live.players.filter(p=>p.connected).length+' PLAYERS';negotiatePeers();refreshLiveConnection();}catch(e){if(live===session){live.failures++;const badge=document.querySelector('#live-connection');if(badge)badge.textContent='Reconnecting…';if(live.failures===3)toast('Connection interrupted. Reconnecting to your room…');if(live.failures>20)endLiveConnection('Connection lost. Rejoin a new room when your connection returns.')}}finally{liveBusy=false;if(live===session)livePoll=setTimeout(pollLive,livePollInterval())}}
function startLiveQuestions(){live.roundStarted=true;live.lastLobby='';profile.difficulty=live.config.mode;activeInvite={keys:live.config.keys,timed:live.config.timed,name:'Your live crew',right:0,ms:0};startArena('mixed');$('#arena').width=1000;$('#arena').height=650;game.w=1000;game.h=650;game.x=500;game.y=325;game.map=selectedMap();game.walls=arenaLayout(game);game.field=paintField(game);$('#map-name').textContent=game.map.name;const status=document.querySelector('.title-row .status');if(status)status.textContent='LIVE CO-OP';game.enemies=[];game.wave=0;spawnWave();$('#arena-subtitle').textContent='LIVE ROOM '+live.code+' · Same ten questions · '+QUESTION_STAGES.find(s=>s.tier===live.config.tier).name;ask()}
function mergeLivePlayers(){if(!game||!live)return;for(const p of live.players){if(!live.units[p.id]){const h=getBattleHero(p.hero,p.level,equipmentForPeer(p)),i=Object.keys(live.units).length;live.units[p.id]={id:p.id,name:p.name,hero:p.hero,level:p.level,armour:h.armour,shieldItem:h.shieldItem,shieldMax:h.shieldMax,shieldCharge:h.shieldMax,shieldClock:0,look:sanitiseLook(p.state.look),weapon:weaponFor(p.state.weapon,p.level).id,x:320+i*160,y:325,hp:h.hp+p.state.right,maxHp:h.hp+10,ammo:h.maxAmmo,charge:0,inv:1.5,cooldown:0,energy:0,shot:p.state.shot||0,super:p.state.super||0,moving:false}}if(p.id!==live.selfId){const unit=live.units[p.id];unit.x=p.state.x;unit.y=p.state.y;unit.moving=p.state.moving}live.units[p.id].connected=p.connected;live.units[p.id].look=sanitiseLook(p.state.look);live.units[p.id].weapon=weaponFor(p.state.weapon,p.level).id}}
function beginLiveBattle(){if(!game)return;live.battleStarted=true;live.ended=false;live.lastLobby='';closeModal();quiz=null;activeInvite=null;game.paused=false;game.elapsed=0;game.time=game.mode.seconds;live.endsAt=Date.now()+game.mode.seconds*1000;game.wave=0;game.enemies=[];game.bullets=[];game.enemyShots=[];game.hazards=[];live.units={};mergeLivePlayers();const me=live.units[live.selfId];if(me){game.x=me.x;game.y=me.y;live.state.x=me.x;live.state.y=me.y}if(live.host){const rank=Math.max(...live.players.map(p=>(getBattleHero(p.hero,p.level,equipmentForPeer(p))).rank));game.tier=rank;const mastery=masteryBonuses(Math.max(...live.players.map(p=>p.level)));game.monsterBonus=2*(rank-1)+2*mastery.damage;game.monsterDamage=1+Math.floor((rank-1)/4)+Math.floor(mastery.hp/3)+(game.mode.id==='expert'?2:game.mode.id==='challenger'?1:0);game.attackPower=Math.max(...live.players.map(p=>(getBattleHero(p.hero,p.level,equipmentForPeer(p))).damage));spawnWave()}$('#arena-subtitle').textContent='LIVE CO-OP · ROOM '+live.code+' · Shared bots & waves';document.querySelector('.wave-hud')?.insertAdjacentHTML('beforeend','<span id="live-connection">● LIVE</span>');document.querySelector('.battle-top')?.insertAdjacentHTML('beforeend','<button class="secondary" data-live="leave">Leave room</button>');resetControls();last=performance.now();$('#arena').focus()}
function liveSnapshot(win){const g=game;if(!g)return{};return{players:Object.values(live.units),enemies:g.enemies,bullets:g.bullets,enemyShots:g.enemyShots,wave:g.wave,kills:g.kills,time:g.time,elapsed:g.elapsed,win:win??live.win??false}}
function applyLiveSnapshot(s){if(!game)return;for(const key of ['enemies','bullets','enemyShots'])game[key]=Array.isArray(s[key])?s[key]:[];for(const key of ['wave','kills','time','elapsed'])if(Number.isFinite(s[key]))game[key]=s[key];game.boss=game.enemies.find(e=>e.type==='boss')||null;for(const p of s.players){const prior=live.units[p.id];live.units[p.id]={...p,renderX:prior?.renderX??p.x,renderY:prior?.renderY??p.y}}const p=live.units[live.selfId];if(p){game.hp=p.hp;game.maxHp=p.maxHp;game.ammo=p.ammo;game.charge=p.charge;if(p.hp<=0)game.moving=false}}
function moveLiveLocal(dt){const g=game,p=live.units[live.selfId];if(!p||p.hp<=0){g.moving=false;return}let dx=+!!(keys.ArrowRight||keys.d)-+!!(keys.ArrowLeft||keys.a),dy=+!!(keys.ArrowDown||keys.s)-+!!(keys.ArrowUp||keys.w);if(stick.pointerId!==null){dx=stick.x;dy=stick.y}const mag=Math.max(1,Math.hypot(dx,dy));if(dx||dy)g.facing={x:dx/mag,y:dy/mag};if(g.dashRemaining>0){g.dashRemaining=Math.max(0,g.dashRemaining-dt);moveBody(g,g,g.facing.x*650*dt,g.facing.y*650*dt,26)}else moveBody(g,g,dx/mag*g.speed*dt,dy/mag*g.speed*dt,26);g.dashCooldown=Math.max(0,g.dashCooldown-dt);g.cooldown=Math.max(0,g.cooldown-dt);g.moving=!!(dx||dy);p.x=g.x;p.y=g.y;p.moving=g.moving;live.state.x=g.x;live.state.y=g.y;if(keys[' ']||firePointerId!==null)shoot()}
function fireLiveUnit(p){const g=game,h=getBattleHero(p.hero,p.level,equipmentForPeer(p));if(p.hp<=0||p.ammo<=0||p.cooldown>0)return;const enemy=g.enemies.filter(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-p.x,e.y-p.y)<460&&lineClear(g,p.x,p.y,e.x,e.y,6)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!enemy)return;const a=Math.atan2(enemy.y-p.y,enemy.x-p.x);g.bullets.push({x:p.x,y:p.y,dx:Math.cos(a)*700,dy:Math.sin(a)*700,life:1.6,damage:h.damage,owner:p.id});p.ammo--;p.cooldown=h.shotDelay;if(p.id===live.selfId)GameAudio.effect('shoot')}
function liveHurt(p){if(p.inv>0||p.hp<=0)return;p.hp=Math.max(0,p.hp-game.monsterDamage);p.inv=1.1;if(p.id===live.selfId)GameAudio.effect('hurt')}
function steerLiveEnemy(e,p,dt){const g=game,a=Math.atan2(p.y-e.y,p.x-e.x);for(const offset of [0,.75,-.75,1.5,-1.5]){const dx=Math.cos(a+offset)*e.speed*dt,dy=Math.sin(a+offset)*e.speed*dt;if(!blocked(g,e.x+dx,e.y+dy,e.r)){moveBody(g,e,dx,dy,e.r);break}}}
function simulateLiveWorld(dt){const g=game,units=Object.values(live.units).filter(p=>p.connected);g.time=Math.max(0,(live.endsAt-Date.now())/1000);g.elapsed+=dt;g.waveFlash=Math.max(0,g.waveFlash-dt);for(const p of units){p.inv=Math.max(0,p.inv-dt);p.cooldown=Math.max(0,p.cooldown-dt);p.energy+=dt;if(p.energy>1.8){p.energy=0;p.ammo=Math.min((getBattleHero(p.hero,p.level,equipmentForPeer(p))).maxAmmo,p.ammo+1)}const state=p.id===live.selfId?live.state:live.players.find(x=>x.id===p.id)?.state;if(state&&state.shot>p.shot){fireLiveUnit(p);p.shot=state.shot}if(state&&state.super>p.super){if(p.charge>=3&&p.hp>0){p.charge=0;const h=getBattleHero(p.hero,p.level,equipmentForPeer(p));g.enemies.filter(e=>Math.hypot(e.x-p.x,e.y-p.y)<g.mode.superRadius).forEach(e=>{e.hp-=h.superDamage;if(e.hp<=0)e.defeatOwner=p.id})}p.super=state.super}}
 for(const e of g.enemies){if(e.hp<=0)continue;e.flash=Math.max(0,(e.flash||0)-dt);e.spawnShield=Math.max(0,(e.spawnShield||0)-dt);if(e.spawnShield>0)continue;const p=units.filter(p=>p.hp>0).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];if(!p)continue;const d=Math.hypot(p.x-e.x,p.y-e.y),a=Math.atan2(p.y-e.y,p.x-e.x);if(d>180||e.type==='scout'||e.type==='tank')steerLiveEnemy(e,p,dt);if(e.type==='boss')e.phase=e.hp<e.maxHp*.5?2:1;e.fire-=dt;if((e.type==='blaster'||e.type==='boss')&&e.fire<=0&&lineClear(g,e.x,e.y,p.x,p.y,8)){const count=e.type==='boss'?5:g.mode.shots;for(let i=0;i<count;i++)emitEnemyShot(g,e,a+(i-(count-1)/2)*.17,210);e.fire=e.type==='boss'?1.5:1.75}if(d<e.r+26)liveHurt(p)}
 for(const b of g.bullets){b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;if(blocked(g,b.x,b.y,4)){b.life=0;continue}const e=g.enemies.find(e=>e.hp>0&&e.spawnShield<=0&&Math.hypot(e.x-b.x,e.y-b.y)<e.r+7);if(e){e.hp-=b.damage||1;if(e.hp<=0)e.defeatOwner=b.owner;e.flash=.15;if(!advancePiercingShot(b,e))b.life=0}}
 g.bullets=g.bullets.filter(b=>b.life>0);for(const b of g.enemyShots){b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;if(blocked(g,b.x,b.y,5)){b.life=0;continue}const p=units.find(p=>p.hp>0&&Math.hypot(p.x-b.x,p.y-b.y)<29);if(p){liveHurt(p);b.life=0}}g.enemyShots=g.enemyShots.filter(b=>b.life>0);g.enemies=g.enemies.filter(e=>{if(e.hp>0)return true;g.kills++;if(e.defeatOwner&&live.units[e.defeatOwner])live.units[e.defeatOwner].defeats=(live.units[e.defeatOwner].defeats||0)+1;units.forEach(p=>p.charge=Math.min(3,p.charge+.5));GameAudio.effect('defeat');return false});
 if(!units.some(p=>p.hp>0)||g.time<=0){finishLiveBattle(false);return}if(!g.enemies.length){if(g.wave>=g.totalWaves)finishLiveBattle(true);else spawnWave()}
 const me=live.units[live.selfId];if(me){g.hp=me.hp;g.maxHp=me.maxHp;g.ammo=me.ammo;g.charge=me.charge;g.shieldMax=me.shieldMax;g.shieldCharge=me.shieldCharge}}
async function finishLiveBattle(win){const session=live;if(!session||session.finishing)return;session.finishing=true;session.win=win;try{await liveAPI('sync',{code:session.code,token:session.token,state:session.state,snapshot:liveSnapshot(win)});if(live!==session)return;await liveAPI('phase',{code:session.code,token:session.token,phase:'results'});if(live!==session)return;session.phase='results';showLiveResults(win)}catch(e){if(live===session){session.finishing=false;toast(e.message)}}}

function showLiveResults(win){if(!live||live.ended)return;live.ended=true;if(game)game.paused=true;resetControls();clearQuestionClock();profile.matches++;if(win){profile.wins++;profile.xp+=selectedMode().bonus;profile.coins+=selectedMode().coins}save();const units=Object.values(live.units);openModal(`${topModal('LIVE CO-OP · TEAM RESULTS')}<div class="results"><div class="result-emblem">${win?'✦':'⚑'}</div><h2 id="modal-title">${win?'Your crew conquered the arena!':'Stronger together. Try again!'}</h2><p>One battlefield. One team. Every heart came from learning.</p><div class="live-roster">${units.map(p=>`<article class="live-peer">${petPortrait(getBattleHero(p.hero,p.level,equipmentForPeer(p)))}<div><b>${safeText(p.name)}</b><small>${p.hp} hearts remaining · ${p.hp>0?'Standing strong':'Cheering on the crew'}</small></div></article>`).join('')}</div><button class="primary" data-live="leave">Back to home →</button></div>`)}
function endLiveConnection(message){clearTimeout(livePoll);live=null;liveDraft=false;quiz=null;if(game)game.paused=true;clearQuestionClock();closeModal();navigate('home');toast(message)}
async function leaveLiveRoom(){const prior=live;clearTimeout(livePoll);live=null;liveDraft=false;quiz=null;clearQuestionClock();closeModal();navigate('home');if(prior)try{await liveAPI('leave',{code:prior.code,token:prior.token})}catch{}}
const soloWave=spawnWave;spawnWave=function(){soloWave();if(live?.battleStarted&&live.host){const scale=1+.3*(live.players.filter(p=>p.connected).length-1);game.enemies.forEach(e=>{e.hp=Math.ceil(e.hp*scale);e.maxHp=e.hp})}};
const soloUpdate=updateArena;updateArena=function(dt){if(!live?.battleStarted||live.phase!=='battle')return soloUpdate(dt);moveLiveLocal(dt);if(live.host&&!live.finishing)simulateLiveWorld(dt);return true};
const soloShoot=shoot;shoot=function(){if(!live?.battleStarted)return soloShoot();if(!game||game.paused||game.cooldown>0||game.hp<=0||game.ammo<=0)return;live.state.shot++;game.cooldown=game.hero.shotDelay;if(!live.host){game.ammo--;GameAudio.effect('shoot')}};
const soloSuper=superAttack;superAttack=function(){if(!live?.battleStarted)return soloSuper();if(game.charge>=3){live.state.super++;GameAudio.effect('super')}};
const soloReload=reloadEnergy;reloadEnergy=function(){if(!live?.battleStarted)return soloReload();toast('Live-room energy recharges automatically. Keep moving!')};
const soloPause=pause;pause=function(){if(!live?.battleStarted)return soloPause();resetControls();toast('The live battle keeps running for your crew. Stay in the arena or leave the room.')};
const soloPet=drawPetPlayer;drawPetPlayer=function(c,g){if(!live?.battleStarted)return soloPet(c,g);for(const p of Object.values(live.units)){const h=getBattleHero(p.hero,p.level,equipmentForPeer(p));const mine=p.id===live.selfId;if(!mine){p.renderX=(p.renderX??p.x)+(p.x-(p.renderX??p.x))*.25;p.renderY=(p.renderY??p.y)+(p.y-(p.renderY??p.y))*.25}c.save();if(p.hp<=0)c.globalAlpha=.35;soloPet(c,{...g,hero:{...h,name:p.name,look:p.look,weapon:p.weapon},x:mine?g.x:p.renderX,y:mine?g.y:p.renderY,moving:mine?g.moving:p.moving,invincible:0,zaps:0,shieldCharge:p.shieldCharge,shieldMax:p.shieldMax});c.fillStyle=mine?'#d5fa59':'#a2efff';c.font='bold 11px sans-serif';c.textAlign='center';c.fillText((mine?'YOU · ':'')+p.name+' · '+p.hp+' ♥',mine?g.x:p.renderX,(mine?g.y:p.renderY)+52);c.restore()}};
const soloPrepResult=preparationResults;preparationResults=function(){if(!live?.roundStarted)return soloPrepResult();const invite=activeInvite;activeInvite=null;friendDraft=false;soloPrepResult();activeInvite=invite;live.state.right=game.questionsRight;live.state.progress=10;live.state.ready=true;live.lastLobby='';drawLiveLobby()};
const soloClose=closeRequest;closeRequest=function(){if(live){if(live.roundStarted&&!live.state.ready)return toast('Finish your questions to join the crew. You can leave using Leave round.');return toast('Use Leave room to exit this live session.')}soloClose()};
const soloPicker=drawTopicPicker;drawTopicPicker=function(keep=true){soloPicker(keep);if(liveDraft){const content=document.querySelector('#modal-content');content.innerHTML=content.innerHTML.replace('BUILD YOUR BATTLE LOADOUT','LIVE ROOM · HOST SETTINGS').replace('Start 10 questions →','Create room →');content.insertAdjacentHTML('beforeend',`<p class="notice">Questions: ${questionStage().name} · Level ${playerLevel()} / 100. All friends get this same round.</p>`)}};
const soloShortcuts=topicShortcuts;topicShortcuts=function(){return soloShortcuts().replace('</div></section>','<button data-live="hub">● Play live with friends</button></div></section>')};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(live&&(b.dataset.page||['leave','done'].includes(b.dataset.action))){e.stopImmediatePropagation();leaveLiveRoom();return}if(!b.dataset.live)return;e.stopImmediatePropagation();try{switch(b.dataset.live){case'hub':liveHub();break;case'create':profile.playerName=cleanName(document.querySelector('#live-name')?.value);if(!profile.playerName){toast('Enter a player nickname.');return}save();chooseBattleTopics();liveDraft=true;drawTopicPicker(false);break;case'join':{const name=cleanName(document.querySelector('#live-name')?.value),code=document.querySelector('#live-code')?.value.trim().toUpperCase();if(!name){toast('Enter a player nickname.');return}profile.playerName=name;save();const data=await liveAPI('join',{name,code,hero:ensureAvatar().id,level:playerLevel()});connectLive(data,false);break}case'start':await liveAPI('phase',{phase:'quiz'});break;case'battle':await liveAPI('phase',{phase:'battle'});break;case'leave':leaveLiveRoom();break;case'copy':try{await navigator.clipboard.writeText(liveRoomLink(live.code));toast('Live room invitation copied.')}catch{document.querySelector('#live-invite')?.select();toast('Copy the invite link shown below.')}break}}catch(error){toast(error.message)}},true);
const gradedPreparation=buildPreparation;buildPreparation=function(subject){const q=gradedPreparation(subject);q.questionStage=live?QUESTION_STAGES.find(s=>s.tier===live.config.tier):questionStage();return q};
const stageAsk=ask;ask=function(){stageAsk();if(quiz&&!live)document.querySelector('#modal-title')?.insertAdjacentHTML('beforebegin',`<p class="question-stage">${(quiz.questionStage||questionStage()).name.toUpperCase()} QUESTIONS</p>`)};
const stageHome=home;home=function(){return stageHome().replace('<section class="player-card">',`<div class="learning-stage"><b>Level ${playerLevel()} · ${questionStage().name} questions</b><span>Years 6–12 · Level 100 mastery.</span></div><section class="player-card">`)};
function openRoomInvite(){if(window.location.hash.startsWith('#room='))liveHub(window.location.hash.slice(6).replace(/[^A-Z2-9]/gi,'').slice(0,8).toUpperCase())}
window.addEventListener('hashchange',openRoomInvite);navigate('home');openRoomInvite();


